@push('scripts')<script>$(function(){function send($b,data){if($b.data('busy'))return;$b.data('busy',1).prop('disabled',true);$.ajax({url:$b.data('url'),method:'POST',data:$.extend({_token:$('meta[name="csrf-token"]').attr('content')},data||{}),headers:{Accept:'application/json'}}).done(function(r){Swal.fire({icon:'success',text:r.msg}).then(function(){location.reload();});}).fail(function(x){Swal.fire({icon:'error',text:x.responseJSON?.message||'ไม่สามารถดำเนินการได้'});}).always(function(){$b.data('busy',0).prop('disabled',false);});}$('.js-action').on('click',function(){var b=$(this);Swal.fire({icon:'question',text:'ยืนยันการดำเนินการ?',showCancelButton:true}).then(function(r){if(r.isConfirmed)send(b);});});$('.js-void,.js-reverse').on('click',function(){var b=$(this),reverse=b.hasClass('js-reverse');Swal.fire({input:'textarea',inputLabel:'เหตุผล',showCancelButton:true,preConfirm:function(v){if(!$.trim(v||'')){Swal.showValidationMessage('กรุณาระบุเหตุผลอย่างน้อย 10 ตัวอักษร');return false;}return v;}}).then(function(r){if(r.isConfirmed)send(b,{reason:r.value,reversal_date:reverse?new Date().toISOString().slice(0,10):undefined});});});});</script>@endpush
